 m=re.match(r'\\s*\"(["'^"'"\\\\]*)\"\\s*:',line)
 if m and m[1] in want and (117<=n<=244 or n>=974):
  print(str(n)+': '+line[:180]+('…' if len(line)>180 else ''))
PY"

